inline drawborad::DocumentSnapshot snapshot(drawborad::ColorMode mode=drawborad::ColorMode::RGB, drawborad::Depth depth=drawborad::Depth::U8, std::uint64_t w=1024, std::uint64_t h=1024){
 using namespace drawborad; ResourceBudget b; NewDocumentRequest r; r.dimensions={double(w),double(h),Unit::Px,300}; r.colorSpec.format={mode,depth,true}; r.colorSpec.profileId=Hash{}; if(mode==ColorMode::CMYK)r.colorSpec.profileId.bytes[0]=1; auto spec=validateDocument(r,b); if(!spec)throw std::runtime_error("fixture spec"); DocumentSnapshot s; s.documentId=Id::fromNumber(99);s.revision=1;s.spec=spec.value();auto ns=std::make_shared<NodeMap>();LayerNode root;root.id=Document::rootId();root.kind=NodeKind::Root;root.name="Document";NodeId obj=Id::fromNumber(2),layer=Id::fromNumber(3);LayerNode o;o.id=obj;o.parent=root.id;o.kind=NodeKind::Object;o.name="Object";o.bounds={0,0,w,h};o.children={layer};LayerNode l;l.id=layer;l.parent=obj;l.objectId=obj;l.kind=NodeKind::Layer;l.name="Layer";l.bounds={0,0,w,h};root.children={obj};ns->emplace(root.id,root);ns->emplace(obj,o);ns->emplace(layer,l);s.nodes=ns;return s; }
inline drawborad::StrokeEvent stroke(const drawborad::DocumentSnapshot& s,double x0,double y0,double x1,double y1,std::uint64_t id=10){using namespace drawborad;StrokeEvent e;e.id=Id::fromNumber(id);e.objectId=Id::fromNumber(2);e.layerId=Id::fromNumber(3);e.startUs=100;e.endUs=200;e.toolId="pencil";e.color.profileId=s.spec.colorSpec.profileId;e.color.activeChannels=s.spec.colorSpec.format.mode==ColorMode::CMYK?4:3;e.color.channels={1,0.2,0.1,0.5};e.color.alpha=1;e.geometry={{x0,y0,1,{}, {},100,0,0},{x1,y1,1,{}, {},200,0,0}};e.seed=id;e.parentRevision=s.revision;e.engineVersion=2;e.style.width=12;e.style.opacity=.8;e.style.hardness=.7;e.style.grain.assign(64,255);return e;}
inline drawborad::DocumentSnapshot withEvents(drawborad::DocumentSnapshot s,std::vector<drawborad::StrokeEvent> e){s.eventIndex=std::make_shared<const drawborad::EventList>(std::move(e));return s;}
